import { Component, Input } from '@angular/core';
import { FormsModule } from '@angular/forms';

import { AmortizacionesComponent } from "./amortizaciones/amortizaciones.component";
import { CotizadorService } from './cotizador.service';

export interface Cotizacion{
  capital: number; // Numeric value with a minimum of 0
  interes_total?:number;
  iva_interes_total?:number;
  interes_anual: number; // Numeric value with a minimum of 0
  incluir_iva: boolean; // Boolean value
  gastos_judiciales?: number; // Numeric value with a minimum of 0
  abono_inicial?:number;
  plazos: number; // Integer value with a minimum of 1
  plazo_tipo: 'MENSUAL' | 'SEMANAL'  // Enum-like value, either 'MENSUAL' or 'SEMANAL'
  fecha_inicio: string | null; // Date value or null
  tipo_tasa: '1' | '2' | 'TASA ORDINARIA ANUAL' | 'TASA INSOLUTA' // Enum-like value
}

export interface Pago {
  fecha           : string;
  pago_fijo       : number;
  abono_a_capital : number;
  interes         : number;
  iva             : number;
  saldo_insoluto  : number;
  saldo_soluto    : number;
  gastos_judiciales: number;
}

interface Totales {
  fecha: string;
  pago_fijo: number;
  abono_a_capital: number;
  interes: number;
  iva: number;
  saldo_insoluto: number;
  saldo_soluto: number;
  gastos_judiciales?:number;
}

export interface PagosResponse {
  lista_pagos: Pago[];
  totales: Totales;
}

@Component({
    selector: 'app-cotizador',
    imports: [
    FormsModule,
    AmortizacionesComponent
],
    templateUrl: './cotizador.component.html',
    styleUrl: './cotizador.component.css'
})
export class CotizadorComponent {
  @Input() div:string='container my-2 rounded shadow p-3 bg-white'
  data: Cotizacion = {
    capital: 100000,
    interes_anual: 24,
    incluir_iva: true,
    gastos_judiciales: 0,
    plazos: 24,
    plazo_tipo: 'MENSUAL',
    fecha_inicio: new Date().toISOString().substring(0,10),
    tipo_tasa: 'TASA ORDINARIA ANUAL'
  };

  amortizaciones?:PagosResponse

  constructor(    
    private cotizadorService: CotizadorService,
  ){}

  async getAmortizaciones(){
    this.amortizaciones=this.cotizadorService.calcularAmortizaciones(this.data)    
  }
}